// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address target) public {
        vm.assume(caller1 != address(0) && target != address(0));

        // Record initial approval status of target
        bool initialApproval = c.approvedLoggers(target);

        // As caller1, try to set approval for target to the opposite
        bool newStatus = !initialApproval;
        vm.prank(caller1);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setApprovedLogger.selector, target, newStatus));

        // The rule: unless caller1 is the owner, the call should revert
        bool isOwner = (caller1 == address(this)); // owner is contract deployer
        // If caller1 is not owner, then success must be false (revert); if owner, success true
        if (isOwner) {
            assertTrue(success, "Owner should succeed");
            // Owner changes state, so check new value
            assertTrue(c.approvedLoggers(target) == newStatus, "Owner can change approval");
        } else {
            assertTrue(!success, "Non-owner should revert");
            assertTrue(c.approvedLoggers(target) == initialApproval, "Non-owner cannot change approval");
        }

        // After the call, approvedToLog(caller1) does not change due to this call (but irrelevant for the rule)
        bool finalApproval = c.approvedLoggers(target);
        if (!isOwner) {
            assertTrue(finalApproval == initialApproval, "Non-owner cannot change approval");
        }
    }
}

